// gateway log 證實收到了，但那輪 agent turn 疑似被 MiniMax 429 卡死，導致 4 小時沒回覆、
// 訊息內容也從沒寫進 memory/YYYY-MM-DD.md——事後完全查不到教練當時說了什麼。
// 這支 hook 在 message:preprocessed（agent 還沒開始處理前）當下就同步寫死一行 log，
// 不管後面那輪 agent turn 成功/失敗/卡死，這行紀錄都已經落地在磁碟上。
// 教練 2026-08-06 拍板：先做這個補強。

const fs = require('fs');
const path = require('path');

const HOME = process.env.HOME;
const LOG_DIR = path.join(HOME, '.openclaw', 'workspace', 'state', 'inbound_echo');
const DEBUG_LOG = path.join(HOME, '.openclaw', 'logs', 'inbound-echo-debug.log');

function debugLog(msg) {
  try {
    fs.appendFileSync(DEBUG_LOG, new Date().toISOString() + ' ' + msg + '\n');
  } catch (e) {}
}

function extractText(event) {
  const c = (event && event.context) || {};
  // c.body 是 openclaw 原始碼查證過的正式欄位（message-hook-mappers.js
  // toInternalInboundMessageHookContextBase），優先採用；其餘留著防未來版本欄位改名。
  const cands = [
    c.body, c.bodyForAgent,
    event.text,
    c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.userMessage,
    (c.message && (typeof c.message === 'string' ? c.message : (c.message.text || c.message.content))),
  ];
  const pickLast = (arr) => {
    if (Array.isArray(arr) && arr.length) {
      const last = arr[arr.length - 1];
      if (typeof last === 'string') return last;
      if (last && typeof last === 'object') return last.text || last.content || '';
    }
    return '';
  };
  cands.push(pickLast(event.messages));
  cands.push(pickLast(c.messages));
  for (const v of cands) if (typeof v === 'string' && v.trim()) return v;
  return '';
}

function resolveAgentId(event) {
  const ctx = (event && event.context) ? event.context : {};
  const raw =
    event.agentId ||
    ctx.agentId ||
    (ctx.agent && ctx.agent.id) ||
    ctx.agent ||
    '';
  if (raw) return String(raw).toLowerCase();
  const sessionKey = event.sessionKey || ctx.sessionKey || '';
  if (sessionKey) {
    const parts = String(sessionKey).split(':');
    if (parts[0] === 'agent' && parts[1]) return parts[1].toLowerCase();
  }
  return 'unknown';
}

function resolveChannel(event) {
  const ctx = (event && event.context) || {};
  if (ctx.channelId) return String(ctx.channelId);
  const sessionKey = String(event.sessionKey || ctx.sessionKey || '');
  const parts = sessionKey.split(':');
  const agentIdx = parts.indexOf('agent');
  if (agentIdx >= 0 && parts[agentIdx + 2]) return parts[agentIdx + 2];
  return 'unknown';
}

// 欄位順序依 openclaw dist/message-hook-mappers 原始碼查證：
// toInternalMessagePreprocessedContext 實際帶的是 senderId/conversationId/from/to，
// 沒有 chatId/source.chat.id 這種巢狀結構（那是別的 hook 事件用的，別搞混）。
function resolveChatId(event) {
  const ctx = (event && event.context) || {};
  const raw = String(
    ctx.senderId || ctx.conversationId || ctx.from || ctx.to ||
    event.from || event.senderId ||
    ctx.chatId || (ctx.source && ctx.source.chat && ctx.source.chat.id) || ''
  );
  // 有些管線會帶 "telegram:6124913915" / "line:uxxxx" 這種 channel 前綴，統一去掉方便比對
  return raw.replace(/^(telegram|line|whatsapp|discord|sms):/i, '');
}

function todayFile() {
  const d = new Date();
  const tzOffset = 8 * 60; // Asia/Taipei
  const local = new Date(d.getTime() + (tzOffset + d.getTimezoneOffset()) * 60000);
  const y = local.getFullYear();
  const m = String(local.getMonth() + 1).padStart(2, '0');
  const day = String(local.getDate()).padStart(2, '0');
  return path.join(LOG_DIR, `${y}-${m}-${day}.jsonl`);
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;

  try {
    const text = extractText(event);
    if (!text) return; // 沒有可辨識文字內容（例如純圖片/貼圖）就不記，避免噪音

    if (!fs.existsSync(LOG_DIR)) fs.mkdirSync(LOG_DIR, { recursive: true });

    const entry = {
      ts: Date.now(),
      iso: new Date().toISOString(),
      agentId: resolveAgentId(event),
      channel: resolveChannel(event),
      chatId: resolveChatId(event),
      sessionKey: event.sessionKey || (event.context && event.context.sessionKey) || '',
      text: text.slice(0, 2000),
    };

    // 同步寫入，收到訊息當下立刻落地，不等 agent turn 跑完
    fs.appendFileSync(todayFile(), JSON.stringify(entry) + '\n');
  } catch (err) {
    debugLog('ERROR ' + (err && err.message));
  }
};

module.exports = handler;
module.exports.default = handler;

