input.text:
(() => {
  // 攔截 fetch 與 window.open，驗證送出內容但不打到正式資料庫、也不真的開付款頁
  window.__calls = []; window.__opened = null;
  const realFetch = window.fetch;
  window.fetch = (url, opts) => { window.__calls.push({url, body: JSON.parse(opts.body)}); return Promise.resolve({ok:true}); };
  window.open = (u) => { window.__opened = u; return null; };

  openRegister('day1');
  const modalShown = document.getElementById('registerModal').classList.contains('show');
  const title = document.getElementById('registerTitle').textContent;

  document.getElementById('regName').value = '測試勿理';
  document.getElementById('regPhone').value = '0900000009';
  document.getElementById('regEmail').value = 'test@example.com';
  document.getElementById('regCompany').value = '測試公司';
  document.getElementById('registerForm').dispatchEvent(new Event('submit', {cancelable:true, bubbles:true}));

  const r1 = {情境:'DAY1單日', modal開啟: modalShown, 標題: title, 送出筆數: window.__calls.length, 送出內容: window.__calls.map(c=>c.body), 付款頁: window.__opened, modal已關閉: !document.getElementById('registerModal').classList.contains('show')};

  window.__calls = []; window.__opened = null;
  openRegister('combo');
  document.getElementById('regName').value = '測試勿理';
  document.getElementById('regPhone').value = '0900000009';
  document.getElementById('registerForm').dispatchEvent(new Event('submit', {cancelable:true, bubbles:true}));
  const r2 = {情境:'兩天套票', 標題: document.getElementById('registerTitle').textContent, 送出筆數: window.__calls.length, slug清單: window.__calls.map(c=>c.body.slug), 付款頁: window.__opened};

  window.fetch = realFetch;
  return [r1, r2];
})()

