(() => {
  const m = document.getElementById('registerModal');
  const box = m.querySelector('.modal-box');
  const cs = getComputedStyle(m), bs = getComputedStyle(box);
  const r = box.getBoundingClientRect();
  return {
    彈窗可見: cs.display,
    彈窗置中: cs.alignItems + '/' + cs.justifyContent,
    方框寬度: Math.round(r.width) + 'px（上限480）',
    方框在視窗內: r.top >= 0 && r.bottom <= window.innerHeight + 1,
    背景色: bs.backgroundColor,
    標題: document.getElementById('registerTitle').textContent,
    欄位: [...box.querySelectorAll('input')].map(i => i.placeholder),
    送出鈕: box.querySelector('button[type=submit]').textContent.trim(),
    略過連結: box.querySelector('a').textContent.trim(),
    關閉鈕: !!box.querySelector('.modal-close'),
  };
})()

(() => {
  openRegister('day1');
  const box = document.querySelector('#registerModal .modal-box');
  const r = box.getBoundingClientRect();
  const inputs = [...box.querySelectorAll('input')].map(i => Math.round(i.getBoundingClientRect().width));
  const btn = box.querySelector('button[type=submit]').getBoundingClientRect();
  return {
    視窗: window.innerWidth + 'x' + window.innerHeight,
